using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using PowerPointIntelligence.AddIn;
internal static class ContextPropertiesTests
{
    private static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
    private static ContextNativeState State(string managed,int id,string key)
    {var d=new ContextDescriptor {ShapeId=id,ManagedType=managed,CanText=true,CanFont=true,CanFill=true,CanOutline=true};if(managed=="indicator"){d.CanText=d.CanFont=false;}return new ContextNativeState {Snapshot=ContextPanelModel.Build(new[]{d},key),Font=new FontSelectionState {Family="Segoe UI",Size=18,Bold=false,Italic=null},Horizontal="center",Vertical="middle",Direction="horizontal",FillColor=0xF8D8A8,TextColor=0x403020,OutlineColor=null};}
    internal static void Run(string output)
    {
        Directory.CreateDirectory(output);int count=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("FAIL property box: "+name);count++;};
        foreach(var failure in new Exception[]{new System.Runtime.InteropServices.COMException(),new System.Runtime.InteropServices.InvalidComObjectException(),new InvalidCastException(),new NotImplementedException(),new InvalidOperationException(),new System.IO.InvalidDataException()})check(ContextPropertiesController.IsInspectionFailure(failure),"interop inspection failure is published rather than escaping UI timer");check(!ContextPropertiesController.IsInspectionFailure(new OutOfMemoryException()),"fatal resource failure is not mislabeled unsupported Office formatting");
        int gestureRequests=0;using(var prompt=new ContextForegroundPrompt(()=>{gestureRequests++;return false;})){check(!prompt.StartRequested&&gestureRequests==0,"focus handoff never activates without a user gesture");var start=All(prompt).OfType<Button>().Single(b=>b.Name=="StartTest");typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(start,new object[]{EventArgs.Empty});check(prompt.StartRequested&&!prompt.RequestAccepted&&gestureRequests==1,"focus handoff preserves denial rather than claiming success");typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(start,new object[]{EventArgs.Empty});check(gestureRequests==1,"focus handoff requests activation only once per gesture");}
        using(var prompt=new ContextForegroundPrompt(()=>true)){var start=All(prompt).OfType<Button>().Single(b=>b.Name=="StartTest");typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(start,new object[]{EventArgs.Empty});check(prompt.StartRequested&&prompt.RequestAccepted&&prompt.DialogResult==DialogResult.OK,"accepted focus handoff returns to foreground verification");}
        int focusRequests=0,focusTicks=0;bool focused=true;var focus=ContextForegroundPolicy.Establish(()=>focused,()=>{focusRequests++;return true;},()=>focusTicks++,()=>focusTicks,3);check(focus.Verified&&focus.InitiallyForeground&&focusRequests==0,"foreground prerequisite never requests focus when already active");
        focused=false;focusRequests=0;focus=ContextForegroundPolicy.Establish(()=>focused,()=>{focusRequests++;focused=true;return true;},()=>{},()=>0,3);check(focus.Verified&&focusRequests==1,"normal focus request must be verified");
        focused=false;focusRequests=0;focusTicks=0;focus=ContextForegroundPolicy.Establish(()=>focused,()=>{focusRequests++;return false;},()=>focusTicks++,()=>focusTicks,3);check(!focus.Verified&&!focus.RequestAccepted&&focusRequests==1&&focusTicks==3,"denied focus request times out without repeated focus stealing");
        focusTicks=0;focus=ContextForegroundPolicy.Establish(()=>false,()=>true,()=>focusTicks++,()=>focusTicks,3);check(!focus.Verified&&focus.RequestAccepted,"accepted request alone cannot establish foreground success");
        focused=false;focusTicks=0;focus=ContextForegroundPolicy.Establish(()=>focused,()=>false,()=>{if(++focusTicks==2)focused=true;},()=>focusTicks,3);check(focus.Verified&&!focus.RequestAccepted,"user activation can satisfy prerequisite after normal request denial");
        bool invalidFocusTimeout=false;try{ContextForegroundPolicy.Establish(()=>true,()=>true,()=>{},()=>0,0);}catch(ArgumentOutOfRangeException){invalidFocusTimeout=true;}check(invalidFocusTimeout,"focus wait requires bounded positive timeout");
        using(var controller=new ContextPropertiesController(null,()=>false,a=>a(),(key,id)=>{})){
            var api=new DemoAutomation(null,null,controller.AutomationState);
            string initial=api.GetContextPropertiesState();check(initial.Contains("kind=\"None\""),"initial observation is safe before UI refresh");
            using(var observed=new ContextPropertiesView()){
                observed.Render(State("text",10,"private-document-token"));typeof(ContextPropertiesController).GetField("view",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,observed);
                typeof(ContextPropertiesController).GetMethod("PublishObservation",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,new object[]{"private-document-token"});
                string expected=api.GetContextPropertiesState();check(expected.Contains("kind=\"Text\"")&&expected.Contains("font=\"true\""),"UI publisher serializes capabilities");check(!expected.Contains("private-document-token"),"observation excludes private target identity");
                Exception error=null;bool insertionRejected=false;int reads=0;var worker=new System.Threading.Thread(()=>{try{for(int i=0;i<1000;i++){if(api.GetContextPropertiesState()!=expected)throw new Exception("Snapshot changed without a UI publication.");reads++;}try{api.InsertChartJson(null);}catch(InvalidOperationException){insertionRejected=true;}}catch(Exception e){error=e;}});worker.IsBackground=true;worker.SetApartmentState(System.Threading.ApartmentState.MTA);worker.Start();check(worker.Join(5000),"external MTA observation does not block waiting for UI dispatch");check(error==null,"external observation does not reject caller thread");check(reads==1000,"external reader receives coherent immutable snapshots");check(insertionRejected,"mutation UI-thread guard remains enforced");
                controller.Hide();check(api.GetContextPropertiesState().Contains("visible=\"false\"")&&api.GetContextPropertiesState().Contains("reason=\"hidden\""),"hide publishes its actual reason");
            }
            typeof(ContextPropertiesController).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,new object[]{false});check(api.GetContextPropertiesState().Contains("reason=\"commands-unavailable\"")&&api.GetContextPropertiesState().Contains("stage=\"availability\""),"unavailable commands are distinguishable from foreground/selection failures");check(api.GetContextPropertiesState().Contains("refreshes=\"1\""),"observation proves refresh loop has run");
            typeof(ContextPropertiesController).GetField("stage",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,"capture");ContextSelectionBridge.InspectionStage="capture.text-style";typeof(ContextPropertiesController).GetMethod("Failure",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,new object[]{new System.Runtime.InteropServices.COMException("private document sentinel",unchecked((int)0x80004005))});controller.Hide("inspection-failed");string diagnostic=api.GetContextPropertiesState();check(diagnostic.Contains("reason=\"inspection-failed\""),"inspection failure is distinct from foreground loss");check(diagnostic.Contains("stage=\"capture:capture.text-style\""),"diagnostic identifies failed native inspection phase");check(diagnostic.Contains("exception=\"COMException\"")&&diagnostic.Contains("hresult=\"0x80004005\""),"diagnostic retains exception type and HRESULT");check(!diagnostic.Contains("private document sentinel"),"diagnostic excludes exception message and document content");
            string beforeReentry=api.GetContextPropertiesState();typeof(ContextPropertiesController).GetField("refreshing",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,true);typeof(ContextPropertiesController).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,new object[]{false});check(api.GetContextPropertiesState()==beforeReentry,"nested refresh cannot overwrite current capture observation");typeof(ContextPropertiesController).GetField("refreshing",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,false);
            controller.Dispose();check(api.GetContextPropertiesState().Contains("reason=\"disposed\""),"disposed controller remains safe for late COM readers");
        }
        using(var view=new ContextPropertiesView()){
            int callbacks=0;string sentKey=null,action=null;view.Command+=(key,id,value)=>{callbacks++;sentKey=key;action=id;};var first=State("text",1,"doc-a:selection-a");view.Render(first);check(All(view).Single(c=>c.AccessibleName=="Font family").Text=="Segoe UI","font family value bound");check(All(view).Single(c=>c.AccessibleName=="Font size in points").Text=="18","font size value bound");check(callbacks==0,"render is read-only and does not dispatch controls");
            check(All(view).Single(c=>c.AccessibleName=="Font family").Enabled,"font available on text");check(All(view).Single(c=>c.AccessibleName=="Horizontal text alignment").Enabled,"alignment available on text");
            var oldAction=All(view).OfType<Button>().Single(b=>(b.Tag as string)=="edit");view.Render(State("indicator",2,"doc-b:selection-b"));check(!All(view).Single(c=>c.AccessibleName=="Font family").Enabled,"indicator native vector group does not expose misleading font fields");check(All(view).Single(c=>c.AccessibleName=="Fill color").Enabled,"indicator color available");
            typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(oldAction,new object[]{EventArgs.Empty});check(sentKey==first.Snapshot.SelectionKey&&action=="action","queued old button retains original selection token");check(!ContextPanelModel.IsCurrent(first.Snapshot,"doc-b:selection-b"),"old target rejected by identity model");
            view.Render(first);var family=All(view).Single(c=>c.AccessibleName=="Font family");typeof(Control).GetMethod("OnEnter",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(family,new object[]{EventArgs.Empty});view.Render(State("text",3,"doc-c:selection-c"));typeof(Control).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(family,new object[]{new KeyEventArgs(Keys.Enter)});check(sentKey==first.Snapshot.SelectionKey&&action=="font-family","in-flight font editor retains original target token");
            var readonlyState=State("text",4,"readonly");readonlyState.Snapshot=ContextPanelModel.Build(new[]{new ContextDescriptor {ShapeId=4}},"readonly");readonlyState.ReadOnly=true;view.Render(readonlyState);check(!All(view).Single(c=>c.AccessibleName=="Fill color").Enabled&&!All(view).Single(c=>c.AccessibleName=="Font family").Enabled,"read-only capability disables editing");
        }
        var kinds=new[]{"text","process-grid","indicator","connector","template","agenda"};using(var sheet=new Bitmap(1040,700))using(var g=Graphics.FromImage(sheet)){
            g.Clear(Color.FromArgb(235,240,246));for(int i=0;i<kinds.Length;i++)using(var v=new ContextPropertiesView()){v.Render(State(kinds[i],i+1,"snapshot:"+i));using(var bitmap=v.Preview()){int ink=0;for(int y=0;y<bitmap.Height;y++)for(int x=0;x<bitmap.Width;x++){var pixel=bitmap.GetPixel(x,y);if(pixel.R<150&&pixel.G<150&&pixel.B<150)ink++;}check(ink>100,"preview contains rendered property controls");g.DrawImageUnscaled(bitmap,10+(i%3)*342,10+(i/3)*345);}}sheet.Save(Path.Combine(output,"context-property-boxes.png"),ImageFormat.Png);
        }
        Console.WriteLine(count+" contextual view assertions passed; synthetic WinForms previews only, native Office lifecycle pending.");
    }
}
